function renderFullNav(t) {
  var screen = state.screen;
  function ic(on){ return on?'#064E3B':'#9CA3AF'; }
  function lb(on){ return 'font-size:10.5px;font-weight:'+(on?700:600)+';color:'+(on?'#064E3B':'#9CA3AF')+';'; }
  return '<div style="position:absolute;left:16px;right:16px;bottom:22px;height:64px;border-radius:9999px;background:rgba(255,255,255,.72);backdrop-filter:blur(16px) saturate(180%);box-shadow:0 8px 24px rgba(15,23,42,.14);border:.5px solid rgba(0,0,0,.06);display:flex;align-items:center;justify-content:space-around;padding:0 6px;">'
    + '<button data-act="goTo" data-arg="home" style="border:none;background:transparent;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;padding:4px 6px;"><svg width="20" height="18" viewBox="0 0 22 20" style="stroke:'+ic(screen==='home')+'"><path d="M2 9L11 2l9 7v9a1 1 0 01-1 1h-5v-6H8v6H3a1 1 0 01-1-1V9z" fill="none" stroke-width="1.8" stroke-linejoin="round"/></svg><span style="'+lb(screen==='home')+'">'+t.tabHome+'</span></button>'
    + '<button data-act="goTo" data-arg="inventory" style="border:none;background:transparent;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;padding:4px 6px;"><svg width="19" height="18" viewBox="0 0 21 20" style="stroke:'+ic(screen==='inventory')+'"><rect x="1" y="6" width="19" height="13" rx="1.5" fill="none" stroke-width="1.8"/><path d="M1 6l3.5-4.5h12L20 6" fill="none" stroke-width="1.8" stroke-linejoin="round"/></svg><span style="'+lb(screen==='inventory')+'">'+t.tabInventory+'</span></button>'
    + '<button data-act="openCamera" style="border:none;background:#064E3B;width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 6px 16px rgba(6,78,59,.35);margin-top:-16px;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.8"><rect x="3" y="7" width="18" height="13" rx="2"/><circle cx="12" cy="13.5" r="3.5"/><path d="M8 7l1.5-2.5h5L16 7"/></svg></button>'
    + '<button data-act="goTo" data-arg="assistant" style="border:none;background:transparent;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;padding:4px 6px;"><svg width="19" height="18" viewBox="0 0 21 20" style="stroke:'+ic(screen==='assistant')+'"><path d="M1 3.5A2 2 0 013 1.5h15a2 2 0 012 2V13a2 2 0 01-2 2H8l-5 4v-4H3a2 2 0 01-2-2V3.5z" fill="none" stroke-width="1.8" stroke-linejoin="round"/></svg><span style="'+lb(screen==='assistant')+'">'+t.tabAssistant+'</span></button>'
    + '<button data-act="openMore" style="border:none;background:transparent;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;padding:4px 6px;"><svg width="18" height="18" viewBox="0 0 20 20"><circle cx="4" cy="10" r="1.7" fill="#9CA3AF"/><circle cx="10" cy="10" r="1.7" fill="#9CA3AF"/><circle cx="16" cy="10" r="1.7" fill="#9CA3AF"/></svg><span style="font-size:10.5px;font-weight:600;color:#9CA3AF;">'+t.more+'</span></button></div>';
}